function legal(kind) {const privacy=kind==='privacy';return `<main id="main" class="page-width"><article class="prose"><div class="eyebrow">${privacy?'PRIVACY, BY DEFAULT':'CLEAR EXPECTATIONS'}</div><h1 style="margin-top:18px">${privacy?t('你的资料，由你决定。','Your information. Your choice.'):t('把规则，说明白。','Clear terms. From the start.')}</h1>${privacy?`<h2>${t('只收集必要的信息','Only what is needed')}</h2><p>${t('我们使用邮箱帮助你登录。我们不要求手机号、身份证号码或家庭地址。你的登录邮箱默认不对外展示。Google 登录仅用于确认账户身份。','We use email to let you sign in. We do not require a phone number, identity document number, or home address. Your sign-in email is private by default. Google sign-in is used to verify your account identity.')}</p><h2>${t('匹配之前，双方不可见','Private until an introduction')}</h2><p>${t('本站没有公开的人才或岗位目录。简历、岗位和联系邮箱仅平台与已建立匹配的相关方可以查看。与平台的一对一私聊，不会进入匹配会话。请勿在资料中填写无关敏感信息。','There are no public directories of people or roles. Profiles, roles, and contact emails are accessible only to HireFerry and introduced parties. Private platform conversations never become part of a shared introduction room. Avoid unrelated sensitive information in your profile.')}</p><h2>${t('谁可以使用这些资料','Who can use this information')}</h2><p>${t('聘渡管理员可以查看和管理账户、简历、岗位与订单，用于撮合、支持与防止滥用。支付由你选择的支付服务商处理，我们不保存银行卡卡号。AI 访问令牌只能在所属账户的权限内操作，你可以随时撤销。','HireFerry administrators can view and manage accounts, résumés, jobs, and orders for introductions, support, and abuse prevention. Your selected payment provider handles checkout; we do not store card numbers. AI access tokens operate only within their account’s permissions and can be revoked at any time.')}</p><h2>${t('保存与删除','Storage and deletion')}</h2><p>${t('资料保存在本站数据库中。需要删除账户或资料时，请联系网站运营者。交易记录与安全记录可能需要继续保留。我们不使用广告追踪器。','Information is stored in this site’s database. Contact the site operator to request account or data deletion. Transaction and security records may need to be retained. We do not use advertising trackers.')}</p>`:`<h2>${t('服务内容','What the service does')}</h2><p>${t('聘渡是 AI 原生的人才匹配平台，由第三方人类 HR 与 AI HR 理解需求、开展初筛和匹配。平台先与求职者和招聘方分别沟通，再开展寻找与联系。求职者可以单独授权多渠道外部联系。我们认真跟进，但不保证录用、招到员工或在特定时间内完成匹配。双方应自行确认工作内容、身份、合同与条件。','HireFerry is an AI-native recruiting platform where third-party human HR and AI HR understand needs, screen candidates, and match both sides. Each side speaks privately with the platform before research, contact, and introductions. Job seekers may separately authorize external outreach. We follow through but do not guarantee an offer, a hire, or a match within a specific time. Both parties should verify the work, identities, contracts, and conditions themselves.')}</p><h2>${t('收费方式','Fees')}</h2><p>${t(`求职者免费。招聘方按次付费，无会员、无月费、不自动续费。招聘方一次性支付 ${money(pricing().onboarding_cents)} 开通账户。每个招聘广告收取固定月薪底薪的 ${percent(pricing().publish_bps)}，一次付费。岗位只能填写底薪，不得混入奖金或提成。发布后标题与底薪不能修改。新岗位每次修改描述收取原底薪的 ${percent(pricing().edit_bps)}，最多 ${pricing().max_edits} 次；已有岗位保留发布时的修改规则。`,`Job seekers use HireFerry for free. Employers pay one-time charges, with no memberships, monthly fees, or automatic renewal. Employers pay ${money(pricing().onboarding_cents)} once to activate an account. Each job advertisement costs ${percent(pricing().publish_bps)} of the fixed base monthly salary, charged once. Salary must exclude bonuses and commission. The title and salary cannot change after publication. New roles cost ${percent(pricing().edit_bps)} of original base salary per description update, up to ${pricing().max_edits} times. Existing roles retain their original update terms.`)}</p><h2>${t('付款与异常处理','Payments and problems')}</h2><p>${t('订单在支付服务商确认到账后生效。重复回调不会重复发布或扣减修改次数。支付成功但无法应用的订单会交由管理员核对。退款、争议或误付款请联系网站运营者处理；请保留订单号。','Orders take effect after the payment provider confirms payment. Duplicate notifications do not republish a role or use another update. Paid orders that cannot be applied are referred for administrator review. Contact the operator about refunds, disputes, or mistaken payments, and keep your order number.')}</p><h2>${t('真实与尊重','Be honest and respectful')}</h2><p>${t('请发布真实招聘与真实简历，不得诈骗、骚扰或索取无关敏感资料。管理员可以处理违规内容、关闭岗位或封禁账户。AI 操作与手动操作遵守同样的权限和计费规则。','Share honest jobs and résumés. Do not use the service for fraud, harassment, or unrelated sensitive data collection. Administrators can remove content, close jobs, or suspend accounts. AI actions follow the same access and fee rules as manual actions.')}</p>`}${state.config?.support_email?`<h2>${t('联系我们','Contact us')}</h2><p><a href="mailto:${encodeURIComponent(state.config.support_email)}" class="help-link">${esc(state.config.support_email)}</a></p>`:''}</article></main>`;}

async function render() {
  const version=++state.render;service.stopChat();state.homeStory?.dispose();state.homeStory=null;document.body.classList.toggle('home-page',location.pathname==='/');state.sculpture?.dispose();state.sculpture=null;document.documentElement.lang=state.lang==='en'?'en':'zh-CN';document.title=(state.config?.name||'HireFerry · 聘渡')+' · '+t('人才双向匹配服务','People-first hiring');
  try {
    if(!state.config) {const results=await Promise.all([api('/api/config'),session()]);state.config=results[0];if(!localStorage.getItem('hireferry-language'))state.lang=state.config.default_language==='en'?'en':'zh';document.documentElement.lang=state.lang==='en'?'en':'zh-CN';}
    let body;const path=location.pathname,tab=qs().get('tab');
    root.innerHTML=header()+`<main class="loading-screen" id="main"><span class="loader" aria-hidden="true"></span><p role="status">${t('正在准备','Getting ready')}</p></main>`+footer();
    if(path==='/')body=home();
    else if(path==='/login'){if(state.user){go('/app');return;}body=login();}
    else if(path==='/jobs'||path==='/people'){await session();go(state.user?'/app?tab=matches':'/login');return;}
    else if(/^\/jobs\/[^/]+$/.test(path))body=await jobDetail(decodeURIComponent(path.split('/')[2]));
    else if(/^\/people\/[^/]+$/.test(path))body=await personDetail(decodeURIComponent(path.split('/')[2]));
    else if(path==='/privacy'||path==='/terms')body=legal(path.slice(1));
    else if(path==='/app'||path.startsWith('/app/')) {
      await session();if(!state.user){go('/login');return;}
      if(path==='/app/jobs/new')body=await jobEditor();
      else if(/^\/app\/jobs\/[^/]+\/edit$/.test(path))body=await jobEditor(decodeURIComponent(path.split('/')[3]));
      else if(qs().has('order')&&!tab)body=await paymentReturn();
      else if(tab==='messages')body=await service.messagesPage();
      else if(tab==='mandate')body=await service.mandatePage();
      else if(tab==='matches')body=await matchesPage();
      else if(tab==='orders')body=await ordersPage();
      else if(tab==='agents')body=await agentsPage();
      else if(tab==='profile')body=await profilePage();
      else if(tab==='jobs'&&state.user.role==='employer')body=await myJobs();
      else body=await service.messagesPage();
    }
    else if(path==='/admin'){await session();body=await adminPage(tab||'overview');}
    else if(path==='/payment/return'||path==='/payment/success'||path==='/checkout/return'){await session();body=await paymentReturn();}
    else body=`<main id="main" class="page-width page-error"><div class="eyebrow" style="justify-content:center">404 / A SMALL DETOUR</div><h1 style="margin-top:20px">${t('这条路，还没有渡口。','This path has no ferry yet.')}</h1><p>${t('页面不存在，或已经被移走。','This page does not exist or has been moved.')}</p><a href="/" data-nav class="button">${t('回到首页','Back to the beginning')}${icon('arrow')}</a></main>`;
    if(state.user&&!state.admin)state.eligibility=await api('/api/ai/eligibility').catch(()=>({eligible:false}));
    if(version!==state.render)return;root.innerHTML=header()+body+footer();if(path==='/')mountHome();
    if((path==='/app'&&(!tab||tab==='messages')&&!qs().has('order'))||(path==='/admin'&&tab==='messages'))service.mountChat();
    if(path.startsWith('/app')&&state.user?.role==='unassigned')chooseRole();
    registerWebMCP();
    if(location.hash){document.getElementById(location.hash.slice(1))?.scrollIntoView();}
  } catch(error) {if(version!==state.render)return;root.innerHTML=header()+`<main id="main" class="page-width page-error"><h1>${t('暂时没能抵达。','We couldn’t get there yet.')}</h1><p>${esc(error.message)}</p><button class="button" data-action="retry">${t('再试一次','Try again')}${icon('arrow')}</button></main>`+footer();}
}

async function adminPage(tab) {
  if(state.bootstrap&&!state.admin)return `<main id="main" class="page-width admin-auth"><div class="admin-auth-top"><span class="icon-badge">${icon('key')}</span><h1>${t('绑定第一把通行密钥','Add your first passkey')}</h1><p>${t('完成后，管理员登录只接受通行密钥。','After this step, administrator sign-in uses passkeys only.')}</p></div><section class="auth-card"><h2>${t('安全地开始。','A secure beginning.')}</h2><p class="subtitle">${t('使用设备指纹、面容或实体安全密钥。一次性密码不会再用于登录。','Use your device’s fingerprint, face recognition, or security key. The one-time password cannot be used to sign in again.')}</p><form data-form="passkey-register"><div class="field"><label for="passkey-name">${t('密钥名称','Passkey name')}</label><input class="input" id="passkey-name" name="name" value="${t('我的主设备','My primary device')}" maxlength="80" required></div><button class="button full" type="submit">${icon('key')}${t('绑定通行密钥','Create a passkey')}</button></form><p class="help">${t('请在可信设备上操作。首次绑定完成后可以再添加备用密钥。','Use a trusted device. You can add backup passkeys after this first one.')}</p></section></main>`;
  if(!state.admin){const s=await api('/api/admin/auth/status');return `<main id="main" class="page-width admin-auth"><div class="admin-auth-top"><span class="icon-badge">${icon('shield')}</span><h1>${t('聘渡总控台','HireFerry control room')}</h1><p>${t('每次相遇背后，都有人认真负责。','Real people, behind every connection.')}</p></div><section class="auth-card"><h2>${s.initialized?t('欢迎回来。','Welcome back.'):t('第一次，安全启程。','A secure first step.')}</h2><p class="subtitle">${s.initialized?t('使用已绑定的通行密钥登录。','Sign in with a registered passkey.'):t('输入在服务器上生成的一次性密码。','Enter the one-time password generated on the server.')}</p>${s.initialized?`<button class="button full" data-action="admin-passkey-login">${icon('key')}${t('使用通行密钥登录','Sign in with a passkey')}</button><p class="help">${t('支持已绑定的指纹、面容与实体安全密钥。','Supports registered device biometrics and security keys.')}</p>`:`<form data-form="admin-bootstrap"><div class="field"><label for="bootstrap-password">${t('一次性密码','One-time password')}</label><input class="input" type="password" id="bootstrap-password" name="password" autocomplete="one-time-code" required></div><button class="button full" type="submit">${t('验证并绑定通行密钥','Verify and add a passkey')}${icon('arrow')}</button></form><p class="help">${t('管理员需要先在 Linux 服务器中运行初始化命令。密码短期有效，仅用于首次绑定。','An administrator must run the initialization command on the Linux server first. The password expires soon and is only for the first passkey setup.')}</p>`}</section></main>`;}
  if(tab==='messages')return service.messagesPage(true);if(tab==='mandates')return service.adminMandates();if(tab==='agents')return service.adminTokens();if(tab==='users')return adminUsers();if(tab==='jobs')return adminJobs();if(tab==='orders')return adminOrders();if(tab==='keys')return adminKeys();if(tab==='matches')return matchesPage(true);return adminOverview();
}
function dateFilter(tab,extra='') {return `<form data-form="admin-filter" data-tab="${tab}" class="filter-row"><label>${t('开始 (UTC)','From (UTC)')} <input class="input" type="date" name="from" value="${esc(qs().get('from')||'')}"></label><label>${t('结束 (UTC)','To (UTC)')} <input class="input" type="date" name="to" value="${esc(qs().get('to')||'')}"></label>${extra}<button class="button secondary small" type="submit">${t('查看','Apply')}</button><a href="/admin?tab=${tab}" data-nav class="text-button">${t('历史全部','All time')}</a></form>`;}
function apiFilter(path) {const p=new URLSearchParams();for(const k of ['from','to','status','q','role','page','mode'])if(qs().get(k))p.set(k,qs().get(k));return path+(p.size?'?'+p:'');}
function chartSvg(series) {
  if(!series?.length)return `<div class="chart-empty">${t('所选时间范围内还没有已确认的收入。','No confirmed revenue in this date range yet.')}</div>`;
  let items=series.map(x=>({...x,revenue_cents:Math.max(0,Number(x.revenue_cents)||0)})).sort((a,b)=>a.date.localeCompare(b.date));
  const monthly=items[0].date.length===7;
  const stamp=d=>Date.parse(d+(d.length===7?'-01T00:00:00Z':'T00:00:00Z'));
  const start=stamp(items[0].date),finish=stamp(items.at(-1).date);
  const byDate=new Map(items.map(x=>[x.date,x])),expanded=[];
  const cursor=new Date(start),limit=monthly?1200:400;
  while(cursor.getTime()<=finish&&expanded.length<=limit){const key=cursor.toISOString().slice(0,monthly?7:10);expanded.push(byDate.get(key)||{date:key,revenue_cents:0,orders:0});if(monthly)cursor.setUTCMonth(cursor.getUTCMonth()+1);else cursor.setUTCDate(cursor.getUTCDate()+1);}
  if(expanded.length<=limit)items=expanded;
  const w=760,h=215,l=55,r=18,top=15,bottom=32,plotw=w-l-r,ploth=h-top-bottom;
  const max=Math.max(...items.map(x=>x.revenue_cents),100),ymax=Math.ceil(max/5/100)*5*100;
  const point=(x,i)=>[l+(finish>start?(stamp(x.date)-start)/(finish-start):.5)*plotw,top+ploth-(x.revenue_cents/ymax)*ploth];
  const points=items.map(point),path=points.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');
  return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${t('按日收入图表，具体金额见订单列表','Revenue by day. Exact amounts are available in the order list.')}">${[0,1,2,3,4].map(i=>{const y=top+ploth-i/4*ploth;return `<line class="chart-grid" x1="${l}" x2="${w-r}" y1="${y}" y2="${y}"/><text x="${l-10}" y="${y+3}" text-anchor="end">${esc(money(ymax*i/4))}</text>`;}).join('')}<path class="chart-area" d="${path} L${points.at(-1)[0]},${top+ploth} L${points[0][0]},${top+ploth} Z"/><path class="chart-line" d="${path}"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${items.length<35?2.5:0}" fill="#20594c"><title>${esc(items[i].date)} · ${esc(money(items[i].revenue_cents))}</title></circle>`).join('')}${items.filter((x,i)=>i===0||i===items.length-1||i%Math.max(1,Math.ceil(items.length/6))===0).map(x=>{const i=items.indexOf(x);return `<text x="${point(x,i)[0]}" y="${h-7}" text-anchor="middle">${esc(x.date.slice(5))}</text>`;}).join('')}</svg>`;
}
async function adminOverview() {const d=await api(apiFilter('/api/admin/overview'));const s=d.stats;const stats=[['users','person',t('全部用户','People'),String(s.users||0),t('求职者与招聘方','Seekers and employers')],['revenue','wallet',d.payment_mode==='test'?t('测试流水','Test payments'):t('实收流水','Live revenue'),money(s.revenue_cents),d.payment_mode==='test'?t('仅测试，不代表实际收入','Test records, not actual income'):t('所选时间内的实际到账','Confirmed payments in range')],['jobs','briefcase',t('招聘中岗位','Open roles'),String(s.active_jobs||0),t('正在寻找合适的人','Ready for the right person')],['orders','receipt',t('已支付订单','Paid orders'),String(s.paid_orders||0),`${s.pending_orders||0} ${t('笔待支付','pending')}`]];return shell(`${heading(t('每次相遇，尽在眼前。','Every connection, in view.'),t('一个简单的总控台，让服务有条不紊。','A simple control room to keep good things moving.'),'','THE CONTROL ROOM')}<div class="panel-header">${dateFilter('overview',`<select class="input" name="mode" aria-label="${t('流水类型','Payment mode')}"><option value="live" ${d.payment_mode==='live'?'selected':''}>${t('实收流水','Live payments')}</option><option value="test" ${d.payment_mode==='test'?'selected':''}>${t('测试流水','Test payments')}</option></select>`)}<span class="pill">${icon('clock')}${qs().get('from')?t('自选时间','Custom range'):t('历史以来','All time')}</span></div><section class="stat-grid">${stats.map(([id,ico,label,val,cap])=>`<article class="stat"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${esc(val)}</div><div class="stat-caption">${esc(cap)}</div></article>`).join('')}</section>${s.review_orders?notice(`${s.review_orders} ${t('笔已收款订单等待人工核对，请在订单页查看。','paid orders need review. Check the order page.')}`,'warning'):''}<section class="panel chart-panel"><div class="chart-header"><h2>${t('收入，随时间展开。','Revenue over time.')}</h2><div class="chart-legend"><span><span class="legend-dot"></span>${d.payment_mode==='test'?t('测试流水 · 人民币','Test payments · CNY'):t('实收流水 · 人民币','Live revenue · CNY')}</span></div></div>${chartSvg(d.series)}<div class="chart-summary">${(d.revenue_by_kind||[]).map(k=>`<span>${kindText(k.kind)}<strong>${money(k.amount_cents)}</strong></span>`).join('')||t('数据来自已验证的支付回调。','Based on verified payment notifications.')}</div></section><section class="panel"><div class="panel-header"><div><h2>${t('最近的订单','Recent orders')}</h2><p>${t('每一笔，都清楚可查。','Every payment, accounted for.')}</p></div><a href="/admin?tab=orders" data-nav class="text-button">${t('查看全部','View all')}${icon('arrow')}</a></div>${orderTable(d.recent_orders||[])}</section><div class="mini-grid" style="margin-top:20px"><section class="panel"><div class="panel-header"><h2>${t('双方的期待','Both sides of the crossing')}</h2>${icon('person')}</div><div class="summary-kpi"><span>${t('求职者','Job seekers')}</span><strong>${s.seekers||0}</strong></div><div class="summary-kpi"><span>${t('招聘方','Employers')}</span><strong>${s.employers||0}</strong></div><div class="summary-kpi"><a href="/admin?tab=matches" data-nav class="text-button">${t('管理人工对接','Manage introductions')}${icon('arrow')}</a></div></section><section class="panel"><div class="panel-header"><h2>${t('从这里继续','Keep things moving')}</h2></div><p class="help">${t('查看新简历，了解新岗位。认真判断双方的需要，再发起对接。','Review new résumés and roles. Understand what each side needs before making an introduction.')}</p><div class="check-list"><a class="text-button" href="/admin?tab=users" data-nav>${t('查看用户与简历','Review people and résumés')}${icon('arrow')}</a><a class="text-button" href="/admin?tab=jobs" data-nav>${t('查看招聘岗位','Review open roles')}${icon('arrow')}</a></div></section></div>`,'overview',true);}
function orderTable(items) {return items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('订单','Order')}</th><th>${t('类型','Type')}</th><th>${t('金额','Amount')}</th><th>${t('状态','Status')}</th><th>${t('支付方式','Provider')}</th><th>${t('时间','Created')}</th></tr></thead><tbody>${items.map(o=>`<tr><td><span class="order-number" title="${esc(o.id)}">${esc(o.id.slice(0,12))}</span></td><td>${kindText(o.kind)}</td><td class="money">${money(o.amount_cents)}</td><td>${badge(o.status)}</td><td>${o.provider==='stripe'?'Stripe':'Waffo'} ${o.live_mode===false?`<span class="test-badge">${t('测试','Test')}</span>`:''}</td><td>${date(o.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty(t('还没有订单。','No orders yet.'),t('实际交易发生后，记录会出现在这里。','Actual transactions will appear here.'),'','receipt');}
